#include <iostream>
#include <vector>
using namespace std;

int main() {
    long long n, m;
    cin >> n >> m;

    vector<long long> v;

    while (n < m) {
        v.push_back(n);
        n *= 2;
    }

    bool cycle = false;

    while (n % m != 0) {
        long long x = n % m;

        for (size_t i = 0; i < v.size(); ++i) {
            if (x == v[i]) {
                cycle = true;
                break;
            }
        }

        if (cycle) {
            cout << "No";
            return 0;
        }

        v.push_back(x);
        n += x;
    }

    cout << "Yes";
    return 0;
}

