        v.push_back(n);
        n *= 2;
    }

    bool found = false;

    while (n % m != 0) {
        long long x = n % m;

        if (find(v.begin(), v.end(), x) != v.end()) {
            cout << "No";
            found = true;
            break;
        }

        v.push_back(x);
        n += x;
    }

    if (!found)
        cout << "Yes";

    return 0;
}

